sys_script_include.script:
var GetProjectKey = Class.create();
GetProjectKey.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	getProjectKey: function() {

        var name = this.getParameter('sysparm_project_name');

        var gr = new GlideRecord('x_2071423_snow_j_0_jira_lookup_projects');
        gr.addQuery('project_name', name);
        gr.query();

        if (gr.next()) {
            return gr.project_key.toString();
        }

        return '';

    },
    type: 'GetProjectKey'
});
